import{_ as n,C as e,o as s,c as l,E as o,a5 as c}from"./chunks/framework.DOB-AMqW.js";const b=JSON.parse('{"title":"Office Pulse Privacy Policy","description":"Privacy Policy for Office Pulse, presented within Policy Hub.","frontmatter":{"title":"Office Pulse Privacy Policy","description":"Privacy Policy for Office Pulse, presented within Policy Hub."},"headers":[],"relativePath":"apps/office-pulse/privacy.md","filePath":"apps/office-pulse/privacy.md"}'),d={name:"apps/office-pulse/privacy.md"};function p(f,a,h,u,m,y){const t=e("AppBreadcrumbs"),i=e("AppSubnav"),r=e("CopyStandaloneUrl");return s(),l("div",null,[o(t,{"app-id":"office-pulse",current:"Privacy Policy"}),o(i,{"app-id":"office-pulse"}),o(r,{path:"/privacy/office-pulse",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Office Pulse privacy policy"}),a[0]||(a[0]=c('<h1 id="privacy-policy-for-office-pulse" tabindex="-1">Privacy Policy for Office Pulse <a class="header-anchor" href="#privacy-policy-for-office-pulse" aria-label="Permalink to &quot;Privacy Policy for Office Pulse&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Office Pulse is a work-organization and productivity application developed by <strong>Anand Raja</strong>. It combines attendance tools, schedules, tasks, notes, work references, and utilities using device-local storage and configured Google Sheets and Google Forms.</p><p>Office Pulse does not include advertising, developer-operated analytics, or a general-purpose developer cloud account.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Office Pulse uses localStorage to retain information and preferences. Depending on the features you use, this can include:</p><ul><li>A pending office entry time, exit time, company or workplace value, comment, status, work-hour settings, and attendance cache</li><li>To-do items, checklist items, stopwatch state, local memos, cue cards, recently viewed Markdown files, sprint-capacity settings, and bookmarks</li><li>Local status, colour, and tracking overrides for memos, Jira-related items, demonstrations, releases, and other work records</li><li>Cached rota data, notification state, navigation or display preferences, and security settings</li></ul><p>These general localStorage records are not encrypted. Do not place secrets, passwords, authentication tokens, full payment-card details, or information you are not permitted to store into free-text fields.</p><h2 id="google-sheets" tabindex="-1">Google Sheets <a class="header-anchor" href="#google-sheets" aria-label="Permalink to &quot;Google Sheets&quot;">​</a></h2><p>Office Pulse reads configured Google Sheets through Google Visualization or CSV endpoints. Sheet data can include attendance entries, office holidays, important dates, achievements, copy or transfer items, support rotas, memos, Jira-related ticket information, tracked-ticket status, bookmarks, office seating allocations, train-seat reference data, credit-card usage reminders, and cue cards.</p><p>Requests disclose the configured spreadsheet and tab identifiers plus standard connection information such as IP address, user agent, request time, and requested resource to Google. Sheet contents are controlled by the sheet owner and may contain workplace or personal information. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>Some fetched attendance and rota information is cached locally to improve availability and performance.</p><h2 id="google-forms" tabindex="-1">Google Forms <a class="header-anchor" href="#google-forms" aria-label="Permalink to &quot;Google Forms&quot;">​</a></h2><p>Office Pulse can open embedded Google Forms or submit selected fields to configured forms after your action. Depending on the feature, submitted fields can include entry and exit times, workplace or company name, work status, comments, achievement titles, dates, links, or transfer notes.</p><p>Google and the form owner receive submitted information. The form owner&#39;s access, retention, and use are governed by their configuration and applicable policies. Review prefilled information before submitting a form.</p><h2 id="local-login-pin-and-biometrics" tabindex="-1">Local Login, PIN, and Biometrics <a class="header-anchor" href="#local-login-pin-and-biometrics" aria-label="Permalink to &quot;Local Login, PIN, and Biometrics&quot;">​</a></h2><p>The primary app login compares a SHA-1 password hash locally and stores a successful-login record in localStorage. The plain-text password is not stored or sent to an Office Pulse server. This client-side gate is not an online account or a high-security identity system.</p><p>An optional 4-to-8-digit application PIN is represented by a salted PBKDF2-SHA-256 verifier. On supported Android devices, optional biometric unlock uses Android BiometricPrompt and Android Keystore. Office Pulse does not receive or store biometric templates. Auto-lock and background-lock preferences are stored locally.</p><p>These controls protect access to the interface but are not substitutes for Android device encryption, a secure device lock, or appropriate workplace access controls.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>If you enable Android log-off reminders and grant notification permission, Office Pulse stores reminder timing and content locally and asks Android to schedule or display the notification. Exact-alarm access may be used where required by Android. Notification titles and messages can be visible on the lock screen according to system settings.</p><h2 id="pdf-export-and-files" tabindex="-1">PDF Export and Files <a class="header-anchor" href="#pdf-export-and-files" aria-label="Permalink to &quot;PDF Export and Files&quot;">​</a></h2><p>Office Pulse can generate attendance reports containing dates, entry and exit times, durations, workplace names, statuses, and comments selected for export. On Android, the report is passed to the system save or share flow. In a browser, the print dialog is used. Exported PDF files are readable outside the app and are handled by the destination you choose.</p><p>The Markdown viewer reads files only after you select them. Selected file names or recently viewed references may be retained locally.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>Office Pulse has no developer-operated analytics, advertising, or telemetry endpoint. The developer does not automatically receive localStorage records, PINs, passwords, notification settings, or exported reports.</p><p>Information submitted to configured Google Forms or stored in configured Google Sheets is available to the applicable form or sheet owner, which may be the developer or an authorized workplace administrator. If you email support, the developer receives the information you choose to include.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the features and Android version, Office Pulse may use internet access for Google Sheets and Forms, notification permission and exact alarms for optional reminders, biometric authentication for optional unlock, and document or sharing access for PDF export and selected Markdown files.</p><p>The reviewed app does not require location, contacts, phone, SMS, camera, microphone, or call-log permissions.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local records remain until removed by the relevant feature, replaced, cleared through Android or browser site-storage settings, or removed when the app is uninstalled. Some caches expire or are refreshed automatically.</p><p>Clearing app data does not delete Google Form submissions, Google Sheet rows, or PDF copies saved or shared elsewhere. Those records must be deleted through the applicable Google account, form or sheet owner, workplace administrator, or file destination.</p><h2 id="workplace-responsibility" tabindex="-1">Workplace Responsibility <a class="header-anchor" href="#workplace-responsibility" aria-label="Permalink to &quot;Workplace Responsibility&quot;">​</a></h2><p>Use Office Pulse only with information you are authorized to access and store. Follow employer policies and applicable privacy, confidentiality, records, and security requirements.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Office Pulse features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',40))])}const v=n(d,[["render",p]]);export{b as __pageData,v as default};
